-- Kevin Adams waterfall challenges, scraped from hikingwnc.com.
--
--   ADAMS500  the 500 List (hikingwnc.com/the-kevin-adams-500-waterfall-challenge/)
--   ADAMS100  the 100 NC Waterfalls Challenge
--
-- Listings are matched to features by name, then disambiguated by the 500
-- page's Location/Hub column: 14 names occur more than once in that list
-- (Grassy Creek Falls three times), so name alone cannot resolve them. Each
-- feature is claimed at most once.
--
-- Deliberately partial. 39 of 500 and 15 of 100 could not be matched with
-- confidence and are left out rather than guessed -- a wrong link would award
-- badge progress that was never earned. See manual-challenge-links.txt.

BEGIN;

INSERT INTO challenges (name) VALUES ('ADAMS500'), ('ADAMS100')
    ON CONFLICT (name) DO NOTHING;

